package com.example.minicommerce.payment.application;
import com.example.minicommerce.shared.config.AppProperties;import com.example.minicommerce.shared.error.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.stereotype.Component;
@Component public class WebhookSignature{private final byte[] secret;public WebhookSignature(AppProperties p){secret=p.payment().webhookSecret().getBytes(StandardCharsets.UTF_8);}public void verify(String body,String signature){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret,"HmacSHA256"));byte[] expected=mac.doFinal(body.getBytes(StandardCharsets.UTF_8));byte[] actual=HexFormat.of().parseHex(signature==null?"":signature);if(!MessageDigest.isEqual(expected,actual))throw new BusinessException(ErrorCode.PAYMENT_SIGNATURE_INVALID,"Webhook 签名无效");}catch(IllegalArgumentException e){throw new BusinessException(ErrorCode.PAYMENT_SIGNATURE_INVALID,"Webhook 签名格式无效");}catch(BusinessException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}}
